(async () => {
  const j = { 'content-type': 'application/json' };
  const ids = {};
  for (const [name, color] of [['Waffle', 'green'], ['Crumpet', 'blue']]) {
    const made = await (await fetch('/api/bots', { method: 'POST', headers: j, body: JSON.stringify({ name }) })).json();
    ids[name] = made.bot.id;
    await fetch('/api/bots/' + made.bot.id, { method: 'PATCH', headers: j, body: JSON.stringify({ color, hidden: true }) });
  }
  localStorage.setItem('qa-crumpet', ids.Crumpet);
  return JSON.stringify(ids);
})()

(() => {
  const crumpet = localStorage.getItem('qa-crumpet');
  const real = window.fetch.bind(window);
  window.fetch = (input, init) => {
    const url = typeof input === 'string' ? input : input.url;
    if (init?.method === 'PATCH' && url.includes('/api/bots/' + crumpet)) {
      return Promise.resolve(new Response(JSON.stringify({ error: 'This bot is busy with a task. Try again when it is done.' }), { status: 409, headers: { 'content-type': 'application/json' } }));
    }
    return real(input, init);
  };
  return true;
})()
